let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
flow.set('mhi_secrets', secrets);
flow.set('mhi_job_started_at', msg.job_started_at);
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=medical_history_import,status=started value=1 ' + nowNs;
return msg;

// `ls` with no matches writes to stderr and exits non-zero — stdout
// (this node's output 1, wired here) is simply empty in that case,
// which is the normal/expected "nothing new to import" outcome, not
// a failure. Same pattern as body_comp_import_flow.json's equivalent node.
const files = (msg.payload || '').split('\n').map(s => s.trim()).filter(Boolean);
if (!files.length) {
    return [null, msg];
}
msg.files = files;
flow.set('mhi_files', files);
return [msg, null];

// Manual fan-out, not Node-RED's core `split` node -- real bug,
// Aug 2026: the generic split node failed to correctly isolate each
// array element when targeting a custom-named message property
// (confirmed via wherewhen_data_export_flow.json's own diagnostic
// node.warn output on Ward's real instance -- every downstream
// message was receiving the same unrelated raw text instead of its
// own array element). The one split node in this project using the
// DEFAULT "payload" property (analysis_engine_flow.json's
// n_ae_split) is confirmed working via real usage, which is what
// narrowed this down to custom-property targeting specifically,
// not split() in general. msg.parts is built by hand to match
// exactly what Node-RED's own split node documents, so the paired
// join node (mode: "auto") downstream needs no changes.
const items = msg.files || [];
const batchId = 'batch_' + Date.now() + '_' + Math.random().toString(36).slice(2);
// Wrapped in an EXTRA array layer -- real bug caught, Aug 2026: a
// function node with a SINGLE output that returns a flat array of
// messages has that array interpreted as "one message per output
// port," so with only 1 output Node-RED took just the first message
// and silently dropped the rest (confirmed: exactly one file -- the
// first measurement -- was ever written, no error). [[...]] is the
// documented way to send many messages down ONE output: the outer
// array is per-output-port, the inner array is the messages for that
// port.
return [items.map((item, i) => {
    const m = Object.assign({}, msg, { payload: item });
    m.parts = { id: batchId, type: 'array', index: i, count: items.length };
    return m;
})];

// msg.payload is now the parsed YAML object (core yaml node, previous
// step) — schema documented in PLAN.md §19. Only `encounters[]` is
// ingested here; symptom_context/therapy_history_reference/
// open_research_items are deliberately left alone (no date to hang an
// incident on, or not incident-shaped data at all — see this tab's info).
const doc = msg.payload || {};
const encounters = Array.isArray(doc.encounters) ? doc.encounters : [];
return { payload: encounters };

// msg.payload is [[encounters from file 1], [encounters from file 2], ...]
// — flatten into one list to push, one incident_push.php call each.
// Re-attach msg.files (lost across the split/join boundary above, since
// join builds a fresh message from the parts) via flow context, same
// pattern body_comp_import_flow.json uses for its own secrets/job_started_at.
const perFile = Array.isArray(msg.payload) ? msg.payload : [];
const flat = [].concat(...perFile);
msg.files = flow.get('mhi_files') || [];
msg.secrets = flow.get('mhi_secrets');
msg.job_started_at = flow.get('mhi_job_started_at');
if (!flat.length) {
    msg.encounter_results = [];
    return [null, msg];
}
msg.encounters = flat;
return [msg, null];

// Manual fan-out, not Node-RED's core `split` node -- real bug,
// Aug 2026: the generic split node failed to correctly isolate each
// array element when targeting a custom-named message property
// (confirmed via wherewhen_data_export_flow.json's own diagnostic
// node.warn output on Ward's real instance -- every downstream
// message was receiving the same unrelated raw text instead of its
// own array element). The one split node in this project using the
// DEFAULT "payload" property (analysis_engine_flow.json's
// n_ae_split) is confirmed working via real usage, which is what
// narrowed this down to custom-property targeting specifically,
// not split() in general. msg.parts is built by hand to match
// exactly what Node-RED's own split node documents, so the paired
// join node (mode: "auto") downstream needs no changes.
const items = msg.encounters || [];
const batchId = 'batch_' + Date.now() + '_' + Math.random().toString(36).slice(2);
// Wrapped in an EXTRA array layer -- real bug caught, Aug 2026: a
// function node with a SINGLE output that returns a flat array of
// messages has that array interpreted as "one message per output
// port," so with only 1 output Node-RED took just the first message
// and silently dropped the rest (confirmed: exactly one file -- the
// first measurement -- was ever written, no error). [[...]] is the
// documented way to send many messages down ONE output: the outer
// array is per-output-port, the inner array is the messages for that
// port.
return [items.map((item, i) => {
    const m = Object.assign({}, msg, { payload: item });
    m.parts = { id: batchId, type: 'array', index: i, count: items.length };
    return m;
})];

// One msg.payload = one YAML encounters[] entry (PLAN.md §19 schema).
// Mapping to api/incident_push.php's expected body, per §19's "Mapping to
// incidents" section:
//  - occurred_at: `date` padded to 00:00:00 (real precision lives in
//    date_precision/date_note text, not implied by the stored timestamp)
//  - medical_evaluation_notes: procedure + outcome + evidence_note,
//    concatenated with labels so each claim's source stays visible
//  - free_notes: notes + date_note
//  - external_ref: the YAML `id` slug — idempotency key on reimport
const e = msg.payload || {};
const secrets = flow.get('mhi_secrets') || msg.secrets;

function section(label, text) {
    return text ? (label + ': ' + text) : '';
}
const evalNotes = [
    section('Procedure', e.procedure),
    section('Outcome', e.outcome),
    section('Evidence', (e.evidence || '') + (e.evidence_note ? ' — ' + e.evidence_note : ''))
].filter(Boolean).join('\n\n');
const freeNotes = [e.notes, section('Date note', e.date_note)].filter(Boolean).join('\n\n');

const body = {
    external_ref: e.id,
    category: (e.category === 'cardiac') ? 'cardiac' : 'medical',
    occurred_at: (e.date || '') + ' 00:00:00',
    medical_evaluation_notes: evalNotes || null,
    free_notes: freeNotes || null
};
if (Array.isArray(e.related_medications) && e.related_medications.length) {
    body.related_medication_name = e.related_medications[0]; // first-listed, best-effort — see §19 "Still open"
}

msg.url = secrets.godaddy_base_url + '/api/incident_push.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify(body);
return msg;

const results = Array.isArray(msg.payload) ? msg.payload : (msg.encounter_results || []);
const inserted = results.filter(r => r && r.success && r.action === 'inserted').length;
const updated = results.filter(r => r && r.success && r.action === 'updated').length;
const failed = results.filter(r => !(r && r.success)).length;
msg.encounter_inserted = inserted;
msg.encounter_updated = updated;
msg.encounter_failed = failed;
msg.secrets = flow.get('mhi_secrets');
msg.job_started_at = flow.get('mhi_job_started_at');

const files = msg.files || flow.get('mhi_files') || [];
if (!files.length) {
    return [null, msg];
}
const quoted = files.map(f => "'" + f.replace(/'/g, "'\\''") + "'").join(' ');
msg.payload = 'mkdir -p /share/lucius_medical_history_import/processed && mv ' + quoted + ' /share/lucius_medical_history_import/processed/';
return [msg, null];

msg.encounter_inserted = 0;
msg.encounter_updated = 0;
msg.encounter_failed = 0;
msg.secrets = flow.get('mhi_secrets');
msg.job_started_at = flow.get('mhi_job_started_at');
return msg;

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at || Date.now()).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=medical_history_import,status=success inserted=' + (msg.encounter_inserted||0) + ',updated=' + (msg.encounter_updated||0) + ',failed=' + (msg.encounter_failed||0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'medical_history_import', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1 };
if (!msg.secrets) msg.secrets = flow.get('mhi_secrets');
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

const nowNs = Date.now() * 1000000;
const detail = ((msg.error && msg.error.message) || 'unknown error').toString();
const source = (msg.error && msg.error.source && msg.error.source.name) || 'unknown node';
const safeDetail = (source + ': ' + detail).replace(/([ ,="])/g, '\\$1');
msg.secrets = flow.get('mhi_secrets');
msg.job_started_at = flow.get('mhi_job_started_at');
msg.influx_finish_point = 'sync_job_runs,job_name=medical_history_import,status=failed,failure_code=flow_error detail="' + safeDetail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'medical_history_import', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: (source + ': ' + detail).slice(0, 250) };
node.warn('Medical History Import failed: ' + source + ': ' + detail);
return msg;

// Ensures the shared status table exists before every write — cheap
// no-op if it already does. Same idempotent CREATE TABLE IF NOT EXISTS
// discipline as godaddy/sql/upgrade_from_3.0.0.sql, just run inline
// rather than as a separate manual step (Ward, Aug 2026 — "a node red
// task that initializes it, and keeps it up to date"). Identical in
// every flow that writes status — duplicated on purpose, matching this
// project's existing preference for self-contained nodes over a shared-
// context module pattern.
msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

// Builds the UPSERT from msg.sqlite_job (set by job_success/job_failed
// above). 'success' mode updates last_success and clears last_error;
// 'failure' mode updates last_error and deliberately leaves last_success
// untouched (a failure shouldn't erase the last known-good run). checkpoint
// is job-specific optional state (only oura_sync uses it, for its self-heal
// fetch window) — only touched when the caller actually supplies one.
function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
    if (j.checkpoint !== undefined && j.checkpoint !== null) setClauses.push('checkpoint=excluded.checkpoint');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
